INSERT INTO `t_assessment_scale` VALUES (1,'PHQ9','国际通用的抑郁症状快速筛查量表，共 9 题，评估最近两周的状态。','请根据你最近两周内，以下症状出现的频率作答。答案没有对错之分，凭真实感受选择即可。','PHQ-9 抑郁自评量表','[{\"text\":\"做事时提不起劲或没有兴趣\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"感到心情低落、沮丧或绝望\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"入睡困难、睡不安稳或睡眠过多\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"感觉疲倦或没有活力\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"食欲不振或吃得太多\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"觉得自己很糟，或觉得自己很失败，或让自己、家人失望\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"对事物专注有困难，例如阅读或看电视时难以集中注意力\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"动作或说话速度缓慢到别人可以察觉，或正好相反——烦躁或坐立不安、动来动去的情况比平常更严重\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"有不如死掉或用某种方式伤害自己的念头\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}],\"crisis\":true}]','[{\"min\":0,\"max\":4,\"label\":\"无抑郁\",\"suggestion\":\"目前情绪状态良好，请继续保持规律作息、适度运动和社交，这些都是情绪的天然保护伞。\"},{\"min\":5,\"max\":9,\"label\":\"轻度抑郁\",\"suggestion\":\"你可能正经历一些情绪低落。建议：保持规律睡眠与运动、每天记录三件让你感觉不错的小事、与信任的人多交流。若两周内无缓解，建议前往学校心理咨询中心或专业机构聊聊。\"},{\"min\":10,\"max\":14,\"label\":\"中度抑郁\",\"suggestion\":\"你的情绪困扰已比较明显，并对日常生活产生一定影响。强烈建议尽快预约心理咨询师或医院心理科进行面对面评估，专业干预效果通常很好。\"},{\"min\":15,\"max\":19,\"label\":\"中重度抑郁\",\"suggestion\":\"你正在承受较大的痛苦。请尽快寻求精神科医生或专业心理咨询的帮助——这是勇敢而正确的选择，且中重度抑郁通过规范治疗大多可以显著好转。\"},{\"min\":20,\"max\":27,\"label\":\"重度抑郁\",\"suggestion\":\"请务必尽快前往医院精神科/心理科就诊，并让家人或朋友知晓你的状况、陪伴你就医。你不需要独自扛着这一切，专业帮助能带来真实的改善。\"}]'),(2,'GAD7','国际通用的焦虑症状快速筛查量表，共 7 题，评估最近两周的状态。','请根据你最近两周内，以下问题困扰你的频率作答。凭真实感受选择即可。','GAD-7 广泛性焦虑量表','[{\"text\":\"感觉紧张、焦虑或急切\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"不能停止或控制担忧\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"对各种各样的事情担忧过多\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"很难放松下来\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"由于不安而无法静坐\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"变得容易烦恼或急躁\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]},{\"text\":\"感到似乎将有可怕的事情发生而害怕\",\"options\":[{\"label\":\"完全不会\",\"score\":0},{\"label\":\"好几天\",\"score\":1},{\"label\":\"一半以上的天数\",\"score\":2},{\"label\":\"几乎每天\",\"score\":3}]}]','[{\"min\":0,\"max\":4,\"label\":\"无焦虑\",\"suggestion\":\"目前焦虑水平较低，继续保持你现在的节奏。可以把运动、深呼吸练习当作日常情绪保养。\"},{\"min\":5,\"max\":9,\"label\":\"轻度焦虑\",\"suggestion\":\"你可能有一些紧绷感。建议尝试：每天 5-10 分钟腹式呼吸或正念练习、减少咖啡因摄入、睡前远离手机。若持续不缓解，可寻求心理咨询支持。\"},{\"min\":10,\"max\":14,\"label\":\"中度焦虑\",\"suggestion\":\"焦虑已明显影响你的状态。建议尽快进行一次专业心理咨询，学习认知行为疗法（CBT）相关的自助技巧，如焦虑日记、渐进式肌肉放松。\"},{\"min\":15,\"max\":21,\"label\":\"重度焦虑\",\"suggestion\":\"你的焦虑程度较高，请尽快寻求精神科医生或专业心理咨询师的帮助。规范治疗后重度焦虑同样可以显著缓解，越早干预效果越好。\"}]'),(3,'PSS10','经典压力知觉自评量表，共 10 题（含反向计分题），评估最近一个月的压力水平。','请根据你最近一个月内的真实感受作答，题目包含正向与反向描述，请逐题认真作答。','PSS-10 知觉压力量表','[{\"text\":\"因为发生了意料之外的事情而感到心烦意乱\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]},{\"text\":\"感觉无法控制自己生活中的重要事情\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]},{\"text\":\"感到紧张不安和有压力\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]},{\"text\":\"自信自己能处理好个人遇到的问题\",\"options\":[{\"label\":\"从不\",\"score\":4},{\"label\":\"偶尔\",\"score\":3},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":1},{\"label\":\"总是\",\"score\":0}]},{\"text\":\"觉得事情正按自己希望的方向发展\",\"options\":[{\"label\":\"从不\",\"score\":4},{\"label\":\"偶尔\",\"score\":3},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":1},{\"label\":\"总是\",\"score\":0}]},{\"text\":\"发现自己无法应付所有必须做的事情\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]},{\"text\":\"能控制自己生活中的恼怒情绪\",\"options\":[{\"label\":\"从不\",\"score\":4},{\"label\":\"偶尔\",\"score\":3},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":1},{\"label\":\"总是\",\"score\":0}]},{\"text\":\"觉得自己能有效应对生活中发生的重大变化\",\"options\":[{\"label\":\"从不\",\"score\":4},{\"label\":\"偶尔\",\"score\":3},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":1},{\"label\":\"总是\",\"score\":0}]},{\"text\":\"对一些自己无法控制的事情感到恼火\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]},{\"text\":\"觉得困难积累得太多，自己无法克服它们\",\"options\":[{\"label\":\"从不\",\"score\":0},{\"label\":\"偶尔\",\"score\":1},{\"label\":\"有时\",\"score\":2},{\"label\":\"时常\",\"score\":3},{\"label\":\"总是\",\"score\":4}]}]','[{\"min\":0,\"max\":13,\"label\":\"低压力\",\"suggestion\":\"你当前的压力知觉处于健康水平，继续保持张弛有度的生活方式。\"},{\"min\":14,\"max\":26,\"label\":\"中等压力\",\"suggestion\":\"你正承受中等程度的压力。建议识别压力源并拆解任务、保证 7 小时以上睡眠、安排让大脑真正休息的爱好，必要时与朋友或咨询师聊聊。\"},{\"min\":27,\"max\":40,\"label\":\"高压力\",\"suggestion\":\"你感知到的压力已处于较高水平，长期如此会损害身心。建议尽快梳理压力来源，主动向信任的人或专业咨询师求助，学习时间管理与放松技巧。\"}]');
